/* Merge two sorted arrays into one sorted result. O(n+m) time, O(n+m) space. */
import java.util.Arrays;public class MergeSortedArrays{static int[]merge(int[]a,int[]b){int[]c=new int[a.length+b.length];int i=0,j=0,k=0;while(i<a.length&&j<b.length)c[k++]=a[i]<=b[j]?a[i++]:b[j++];while(i<a.length)c[k++]=a[i++];while(j<b.length)c[k++]=b[j++];return c;}public static void main(String[]x){System.out.println(Arrays.toString(merge(new int[]{1,3,5},new int[]{2,4,6})));}}